export interface SecurityKey {
  id: string;
  name: string;
  createdAt: string;
  /** @nullable */
  lastUsedAt: string | null;
}

export interface TwoStepRequirement {
  organizationId: string;
  /** `admins` (owner and admins) or `everyone` today (`x-extensible-enum`). */
  requiredFor: string;
}

/**
 * The two-step verification of an account, without any secret.
 */
export interface TwoStepVerification {
  /** On while the account has an authenticator app. */
  enabled: boolean;
  /** `authenticator-app` today; `null` while off. */
  primaryMethod: TwoStepMethod | null;
  /**
     * The configured methods, `authenticator-app` and `security-key` today, never
     * `backup-code`; empty while off. No upper bound: later versions may add methods.
     */
  methods: TwoStepMethod[];
  /** @nullable */
  authenticatorApp: TwoStepVerificationAuthenticatorApp;
  /**
     * The oldest first.
     * @maxItems 10
     */
  securityKeys: SecurityKey[];
  /** @nullable */
  backupCodes: TwoStepVerificationBackupCodes;
  /**
     * The organizations of the copy of the memberships whose policy requires two-step
     * verification for the role of the person in them.
     */
  requiredBy: TwoStepRequirement[];
}

export interface SessionReference {
  /** The session of the public request, whose recent authentication is checked and which the pending setup belongs to. */
  sessionId: string;
}

export interface TwoStepChange {
  /** The session of the public request, whose recent authentication is checked. */
  sessionId: string;
  /** The browser of the change, shown in the security email. */
  client: Client;
}

export interface AuthenticatorAppSetup {
  /**
     * The TOTP secret (160 bits, base32 without padding), returned once. Never logged.
     * @pattern ^[A-Z2-7]{32}$
     */
  secret: string;
  /**
     * The `otpauth://totp/…` URI of the secret, issuer `Cadenway`. Never logged.
     * @maxLength 2048
     */
  otpauthUri: string;
  /** 15 minutes after the start. */
  expiresAt: string;
}

export interface AuthenticatorAppConfirmation {
  /** The session of the public request, whose pending setup is confirmed. */
  sessionId: string;
  code: TwoStepCode;
  /** The browser of the change, shown in the security email. */
  client: Client;
}

export interface BackupCodes {
  /**
     * 10 codes `XXXX-XXXX`, returned once; identity-service keeps only their HMAC-SHA-256
     * under a key derived from the pepper, outside the database, as for the one-time codes.
     * Never logged.
     * @minItems 10
     * @maxItems 10
     * @items.pattern ^[0-9A-Z]{4}-[0-9A-Z]{4}$
     */
  codes: string[];
  generatedAt: string;
}

export interface AuthenticatorAppConfigured {
  twoStepVerification: TwoStepVerification;
  /** The 10 backup codes when two-step verification turned on, returned once; `null` for a reconfiguration. */
  backupCodes: BackupCodes | null;
}

export interface SecurityKeyRegistration {
  options: WebAuthnCreationOptions;
  /** 5 minutes after the start. */
  expiresAt: string;
}

export interface SecurityKeyAddition {
  /** The session of the public request, whose pending registration is answered. */
  sessionId: string;
  /**
     * Trimmed here; a name made only of spaces answers `400 request.invalid`.
     * @minLength 1
     * @maxLength 60
     */
  name: string;
  credential: SecurityKeyAttestation;
  /** The browser of the change, shown in the security email. */
  client: Client;
}

/**
 * Members of the copy of the memberships whose account has no two-step verification.
 */
export type AuthenticationPolicyMembersWithoutTwoStepVerification = {
  /**
     * The owner and the admins among them.
     * @minimum 0
     */
  admins: number;
  /**
     * All of them, guests included.
     * @minimum 0
     */
  everyone: number;
};

export interface AuthenticationPolicy {
  /** `nobody` (default), `admins` or `everyone` today (`x-extensible-enum`). */
  twoStepVerificationRequiredFor: string;
  /**
     * `60`, `720` (default), `10080` or `43200` today (`x-extensible-enum`).
     * @minimum 1
     */
  sessionInactivityTimeoutMinutes: number;
  /** Members of the copy of the memberships whose account has no two-step verification. */
  membersWithoutTwoStepVerification: AuthenticationPolicyMembersWithoutTwoStepVerification;
  /**
     * Version of the policy, also sent as `ETag`; 1 for the default policy.
     * @minimum 1
     */
  version: number;
}

export type AuthenticationPolicyPatchTwoStepVerificationRequiredFor = typeof AuthenticationPolicyPatchTwoStepVerificationRequiredFor[keyof typeof AuthenticationPolicyPatchTwoStepVerificationRequiredFor];


export const AuthenticationPolicyPatchTwoStepVerificationRequiredFor = {
  nobody: 'nobody',
  admins: 'admins',
  everyone: 'everyone',
} as const;

export type AuthenticationPolicyPatchSessionInactivityTimeoutMinutes = typeof AuthenticationPolicyPatchSessionInactivityTimeoutMinutes[keyof typeof AuthenticationPolicyPatchSessionInactivityTimeoutMinutes];


export const AuthenticationPolicyPatchSessionInactivityTimeoutMinutes = {
  NUMBER_60: 60,
  NUMBER_720: 720,
  NUMBER_10080: 10080,
  NUMBER_43200: 43200,
} as const;

/**
 * JSON Merge Patch of the policy, as the public request carried it.
 */
export interface AuthenticationPolicyPatch {
  twoStepVerificationRequiredFor?: AuthenticationPolicyPatchTwoStepVerificationRequiredFor;
  sessionInactivityTimeoutMinutes?: AuthenticationPolicyPatchSessionInactivityTimeoutMinutes;
}

/**
 * Opaque reservation identifier, reused for the verified immutable asset.
 * @pattern ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-7[0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$
 */
export type ProfileMediaId = string;

/**
 * Kind of owner and the policy used to verify its image.
 */
export type ProfileMediaKind = typeof ProfileMediaKind[keyof typeof ProfileMediaKind];


export const ProfileMediaKind = {
  avatar: 'avatar',
  'organization-logo': 'organization-logo',
} as const;

/**
 * An avatar source is a square PNG, JPEG or WebP image at least 256 pixels on each side.
 */
export type AvatarUploadContentType = typeof AvatarUploadContentType[keyof typeof AvatarUploadContentType];


export const AvatarUploadContentType = {
  'image/png': 'image/png',
  'image/jpeg': 'image/jpeg',
  'image/webp': 'image/webp',
} as const;

/**
 * A logo source is a square PNG or SVG image. A 512-pixel image is recommended.
 */
export type OrganizationLogoUploadContentType = typeof OrganizationLogoUploadContentType[keyof typeof OrganizationLogoUploadContentType];


export const OrganizationLogoUploadContentType = {
  'image/png': 'image/png',
  'image/svg+xml': 'image/svg+xml',
} as const;

/**
 * Image size in bytes, up to 5 MiB.
 * @minimum 1
 * @maximum 5242880
 */
export type ProfileMediaSizeBytes = number;

export interface StartAvatarUpload {
  contentType: AvatarUploadContentType;
  sizeBytes: ProfileMediaSizeBytes;
}

export interface StartOrganizationLogoUpload {
  contentType: OrganizationLogoUploadContentType;
  sizeBytes: ProfileMediaSizeBytes;
}

/**
 * Signed form fields to append unchanged before the file part.
 */
export type ProfileMediaUploadFields = {[key: string]: string};

export interface ProfileMediaUpload {
  uploadId: ProfileMediaId;
  method: 'POST';
  /** Signed multipart destination, valid for at most five minutes and never beyond the reservation expiry. */
  url: string;
  /** Signed form fields to append unchanged before the file part. */
  fields: ProfileMediaUploadFields;
  /** Exclusive expiry of the signed transfer. */
  expiresAt: string;
}

export interface SetProfileMedia {
  uploadId: ProfileMediaId;
}

export interface ProfileMediaReservation {
  uploadId: ProfileMediaId;
  /** Exclusive owner reservation expiry. Replays preserve this instant. */
  expiresAt: string;
}

/**
 * Pending permits preparation within the lease. Committed identifies the same owner receipt on replay.
 */
export type ProfileMediaReservationStateState = typeof ProfileMediaReservationStateState[keyof typeof ProfileMediaReservationStateState];


export const ProfileMediaReservationStateState = {
  pending: 'pending',
  committed: 'committed',
} as const;

export interface ProfileMediaReservationState {
  uploadId: ProfileMediaId;
  /** Pending permits preparation within the lease. Committed identifies the same owner receipt on replay. */
  state: ProfileMediaReservationStateState;
  /** Exclusive owner reservation expiry. Replays preserve this instant. */
  expiresAt: string;
}

export interface CurrentAvatarReference {
  /** The current avatar, or null when the account has no avatar. */
  assetId: ProfileMediaId | null;
}

export interface PrepareProfileMedia {
  kind: ProfileMediaKind;
}

/**
 * The media declaration and exclusive expiry already authorized by the owner service.
 */
export type SignProfileMediaTransfer = {
  kind: 'avatar';
  expiresAt: string;
  contentType: AvatarUploadContentType;
  sizeBytes: ProfileMediaSizeBytes;
} | {
  kind: 'organization-logo';
  expiresAt: string;
  contentType: OrganizationLogoUploadContentType;
  sizeBytes: ProfileMediaSizeBytes;
};

/**
 * The width or height of the square prepared PNG in pixels.
 * @minimum 1
 * @maximum 512
 */
export type ProfileMediaRasterDimension = number;

/**
 * Verified PNG metadata for the immutable upload. Storage verifies the same source bytes it
 * prepares, limits each decoded dimension to 4096 pixels and the decoded image to 4096²
 * pixels, and produces a square PNG of at most 512 pixels per side without source metadata.
 * A supported static SVG logo is rasterized with limits on resources and no external access.
 */
export interface ProfileMediaPreparation {
  uploadId: ProfileMediaId;
  contentType: 'image/png';
  width: ProfileMediaRasterDimension;
  height: ProfileMediaRasterDimension;
  sizeBytes: ProfileMediaSizeBytes;
}

/**
 * Members specific to the code, for example the fields that failed validation.
 */
export type ProblemDetails = { [key: string]: unknown };

/**
 * RFC 9457 problem with the Cadenway extensions `code` and `details`.
 */
export interface Problem {
  /** URI reference that identifies the problem type. */
  type: string;
  /** Short summary of the problem type, the same for every occurrence. */
  title: string;
  /** HTTP status of the response. */
  status: number;
  /** Explanation specific to this occurrence. */
  detail?: string;
  /** URI reference that identifies this occurrence. */
  instance?: string;
  /** Stable machine code, `<domain>.<reason>`. */
  code: string;
  /** Members specific to the code, for example the fields that failed validation. */
  details?: ProblemDetails;
}

/**
 * `idempotency.request-in-progress` when the equivalent signing or owner reservation is running.
 */
export type ProfileMediaReservationConflictResponse = Problem;

/**
 * `media.file-too-large` above 5,242,880 declared bytes, `media.unsupported-type` for a
 * disallowed image encoding, or `idempotency.key-reused` for a conflicting reservation.
 */
export type ProfileMediaReservationRefusedResponse = Problem;

/**
 * `media.upload-expired` for expiration, `media.upload-not-ready` for an upload that has not
 * arrived, or `media.upload-superseded` for an invalidated prior generation.
 */
export type ProfileMediaUploadStateConflictResponse = Problem;

/**
 * `user.not-found` for a different or unavailable account, or `media.not-found` for an absent or unrelated upload.
 */
export type AvatarOwnerOrUploadNotFoundResponse = Problem;

/**
 * The account has two-step verification: no session, no token. The body is the challenge, the
 * schema `POST /internal/v1/auth/sign-in/challenge/inspection` answers; `token` is a secret.
 */
export type ChallengeIssuedResponse = SignInChallenge;

/**
 * A session is open, as for `SessionIssued`; with `trustDevice`, `trustedDevice` holds the
 * device token, returned once, that the gateway writes into `__Host-cw_trusted_device`.
 */
export type ChallengeAnsweredResponse = SessionIssued;

/**
 * `auth.challenge-expired`: the challenge expired (10 minutes), was answered, was replaced,
 * or is unknown or malformed.
 */
export type ChallengeExpiredResponse = Problem;

/**
 * `auth.challenge-expired` (checked first, no attempt counted), then
 * `auth.two-step-code-invalid` with `details.remainingAttempts` (at least 1): the code is
 * wrong or was used already.
 */
export type TwoStepCodeRefusedResponse = Problem;

/**
 * `auth.challenge-expired` (checked first), then `auth.security-key-refused`: no key on the
 * account (options), or an answer that does not verify (answer, with
 * `details.remainingAttempts`).
 */
export type SecurityKeyAnswerRefusedResponse = Problem;

/**
 * `auth.two-step-locked`: the two-step answers of the account are locked until
 * `details.lockedUntil`, 15 minutes after the fifth wrong answer in a row.
 */
export type TwoStepLockedResponse = Problem;

/**
 * `auth.mfa-required-by-organization`: the policy of an organization of the copy of the
 * memberships requires two-step verification for the role of the actor in it;
 * `details.organizationIds` lists them.
 */
export type MfaRequiredByOrganizationResponse = Problem;

/**
 * `auth.two-step-setup-expired`: no pending setup of the session, or it expired or was
 * replaced; `auth.two-step-code-invalid`: a wrong code, without `details.remainingAttempts`.
 */
export type SetupCodeRefusedResponse = Problem;

/**
 * `auth.two-step-not-enabled`: the request needs two-step verification on the account of the
 * actor: backup codes, a security key, a `code` of the re-authentication, or a policy that
 * requires it for a role of the actor.
 */
export type TwoStepNotEnabledResponse = Problem;

/**
 * `auth.two-step-not-enabled` (two-step verification off), or
 * `auth.security-key-limit-reached` (10 keys, with `details.maxSecurityKeys`).
 */
export type SecurityKeyNotAddableResponse = Problem;

/**
 * `auth.two-step-setup-expired`: no pending registration of the session, or it expired or
 * was replaced; `auth.security-key-refused`: the answer does not verify, or the account
 * already has the key.
 */
export type SecurityKeyRegistrationRefusedResponse = Problem;

/**
 * - `user.not-found`: the user id is not the actor, or no account has it;
 * - `session.not-found`: the session of the request is not an open session of the actor. The
 *   gateway answers it as `401 auth.session-expired`;
 * - `security-key.not-found`: no key with this id belongs to the actor.
 */
export type UserSessionOrSecurityKeyNotFoundResponse = Problem;

/**
 * - `organization.mfa-required`: the policy of the organization requires two-step
 *   verification for the role of the actor, who has none; `details.organizationId` names it.
 *   The gateway forwards it with the French title of `openapi/public/organizations.yaml`;
 * - `auth.issuer-not-allowed`, `auth.actor-not-allowed`: see the internal token.
 */
export type OrganizationChoiceRefusedResponse = Problem;

/**
 * - `organization.role-forbidden`: only the owner and the admins of the organization, in the
 *   copy of the memberships, read and change its policy;
 * - `auth.reauthentication-required`, on a change: the session has no authentication in the
 *   last 10 minutes, with `details.methods`; the gateway forwards it with its French title;
 * - `auth.issuer-not-allowed`, `auth.actor-not-allowed`, `auth.organization-required`: see
 *   the internal token.
 */
export type PolicyAccessRefusedResponse = Problem;

/**
 * - `organization.not-found`: the copy of the memberships holds no membership of the actor
 *   in the organization of the token;
 * - `session.not-found`: `sessionId` is not an open session of the actor. The gateway
 *   answers it as `401 auth.session-expired`.
 */
export type OrganizationOrSessionNotFoundResponse = Problem;

/**
 * `organization.not-found`: the copy of the memberships holds no membership of the actor in
 * the organization of the token.
 */
export type OrganizationNotFoundResponse = Problem;

/**
 * A session is open. `token` is returned here only, once: the gateway sets the cookie from it
 * and from `session` (`Max-Age` when `persistent`).
 */
export type SessionIssuedResponse = SessionIssued;

/**
 * `request.invalid`: the request does not match the schema; one `details.issues` entry per issue.
 */
export type BadRequestResponse = Problem;

/**
 * The internal token is missing (`auth.token-missing`) or refused (`auth.token-invalid`, with
 * `details.reason`). The gateway's client reports it as `503 upstream.unauthorized`.
 */
export type InternalTokenRefusedResponse = Problem;

/**
 * The internal token is valid but the route does not accept its issuer
 * (`auth.issuer-not-allowed`) or its actor (`auth.actor-not-allowed`), or the route requires
 * an organization the token does not carry (`auth.organization-required`).
 */
export type InternalAccessRefusedResponse = Problem;

/**
 * - `auth.email-not-verified`: the password is right but the address is not verified yet;
 * - `auth.issuer-not-allowed`, `auth.actor-not-allowed`: see the internal token.
 */
export type SignInForbiddenResponse = Problem;

/**
 * `auth.email-taken`: a verified account already uses the address.
 */
export type EmailTakenResponse = Problem;

/**
 * `auth.terms-not-accepted`, `auth.password-too-short` (with `details.minLength`) or
 * `auth.password-compromised`; nothing is created.
 */
export type SignUpRefusedResponse = Problem;

/**
 * `auth.code-invalid` (wrong code, or no account awaits one at the address) or
 * `auth.code-expired` (expired, used, replaced or too many wrong attempts).
 */
export type CodeRefusedResponse = Problem;

/**
 * The code is checked first: `auth.code-invalid` or `auth.code-expired`, as in
 * `CodeRefused`. Then, only with the right code, `auth.sign-up-replaced`: `password` differs
 * from the password of the latest sign-up of the address, or is missing while the address
 * was signed up more than once; the code stops working.
 */
export type SignUpVerificationRefusedResponse = Problem;

/**
 * `auth.invalid-credentials`, with `details.remainingAttempts` (at least 1); the same when no
 * account uses the address.
 */
export type CredentialsRefusedResponse = Problem;

/**
 * `auth.account-locked`: the password sign-in of the address is locked until
 * `details.lockedUntil`, 15 minutes after the failure that used the last attempt. On the
 * re-authentication with a `code`: `auth.two-step-locked` instead (see `TwoStepLocked`).
 */
export type AccountLockedResponse = Problem;

/**
 * `auth.code-throttled`, with `details.resendAvailableAt`: the code requests of the address
 * are throttled whatever their purpose, account or not, so the sign-up, the sign-up code,
 * the sign-in code and the change of address, counted on the new address, count together. A
 * request is refused less than 30 seconds after
 * the last accepted one, and once 5 were accepted in the current hour, which starts with the
 * first request accepted after the previous hour ended. `details.resendAvailableAt` is 30
 * seconds after the last accepted request, or the end of the hour.
 */
export type CodeThrottledResponse = Problem;

/**
 * `session.not-found`: no session with this id belongs to the actor.
 */
export type SessionNotFoundResponse = Problem;

/**
 * `user.not-found`: no account with this id is readable by the actor.
 */
export type UserNotFoundResponse = Problem;

/**
 * - `session.not-found`: no session with this id belongs to the actor;
 * - `organization.not-found`: the copy of the memberships holds no membership of the actor in
 *   this organization, also for a few seconds after a creation or an acceptance.
 */
export type SessionOrOrganizationNotFoundResponse = Problem;

/**
 * `api-token.not-found`: no token with this id belongs to the actor in the organization of the internal token.
 */
export type ApiTokenNotFoundResponse = Problem;

/**
 * `request.version-mismatch`: `If-Match` is not the current version, with `details.version`.
 */
export type VersionMismatchResponse = Problem;

/**
 * `auth.reset-throttled`, with `details.resendAvailableAt`: the password reset requests of
 * the address are throttled, account or not, apart from the code requests. A request is
 * refused less than 45 seconds after the last accepted one, and once 5 were accepted in the
 * current hour, which starts with the first request accepted after the previous hour ended.
 * `details.resendAvailableAt` is 45 seconds after the last accepted request, or the end of
 * the hour.
 */
export type ResetThrottledResponse = Problem;

/**
 * `auth.reset-link-expired`: the link expired, was used, was replaced, or is unknown or malformed.
 */
export type ResetLinkExpiredResponse = Problem;

/**
 * `auth.reset-link-expired` (the link is checked first), then `auth.password-too-short`
 * (with `details.minLength`) or `auth.password-compromised`, which leave the link usable.
 */
export type PasswordResetRefusedResponse = Problem;

/**
 * `auth.password-incorrect`, with `details.remainingAttempts` (at least 1): the failures left
 * before the lockout of the password sign-in of the address of the account. On the
 * re-authentication with a `code`: `auth.two-step-code-invalid`, with
 * `details.remainingAttempts` before the lockout of the two-step answers of the account.
 */
export type PasswordRefusedResponse = Problem;

/**
 * The new password first: `auth.password-too-short` (with `details.minLength`) or
 * `auth.password-compromised`, no attempt counted; then the current one:
 * `auth.password-incorrect`, with `details.remainingAttempts`.
 */
export type PasswordChangeRefusedResponse = Problem;

/**
 * - `auth.reauthentication-required`: the session has no authentication in the last 10
 *   minutes that counts for its account, or the re-authentication sent a password for an
 *   account with two-step verification. `details.methods` lists the ways its person can
 *   confirm: `[password]` without two-step verification, `[authenticator-app]` with it; the
 *   gateway forwards the code, its `details` and the French title of
 *   `openapi/public/auth.yaml`;
 * - `auth.issuer-not-allowed`, `auth.actor-not-allowed`, and `auth.organization-required` on
 *   a route that requires an organization: see the internal token.
 */
export type RecentAuthenticationRequiredResponse = Problem;

/**
 * `auth.email-unchanged`: the new address is the current address of the account.
 */
export type EmailUnchangedResponse = Problem;

/**
 * `auth.code-invalid` (wrong code, or no pending change of address) or `auth.code-expired`
 * (expired, used, replaced by a newer request or too many wrong attempts).
 */
export type EmailChangeCodeRefusedResponse = Problem;

/**
 * `account.organization-owner`: the copy of the memberships holds a membership of the actor
 * with the role `owner`, not removed. `details.organizationIds` lists those organizations.
 */
export type OrganizationOwnerResponse = Problem;

/**
 * - `user.not-found`: the user id is not the actor, or no account has it;
 * - `session.not-found`: the session of the request is not an open session of the actor. The
 *   gateway answers it as `401 auth.session-expired`.
 */
export type UserOrSessionNotFoundResponse = Problem;

export type ListUserSessionsInternalParams = {
  /** The session of the public request, as the introspection returned it. */
  currentSessionId: string;
  /** Opaque cursor taken from the `nextCursor` of the previous page. */
  cursor?: string;
  /**
   * Page size.
   * @minimum 1
   * @maximum 100
   */
  limit?: number;
};

export type UpdateAuthenticationPolicyInternalParams = {
  /** The session of the public request, as the introspection returned it, whose recent authentication is checked. */
  sessionId: string;
};

export type ListApiTokensInternalParams = {
  /** Opaque cursor taken from the `nextCursor` of the previous page. */
  cursor?: string;
  /**
   * Page size.
   * @minimum 1
   * @maximum 100
   */
  limit?: number;
};

